/* ============================================================
   globe-bg.js — QNetSys
   Globo 3D decorativo (Three.js) detrás de la sección de Contacto.
   Adaptado del demo "Interactive Dotted Globe": sin panel de
   customización, sin drag (el div es pointer-events:none), y con
   tamaño atado al contenedor #globe-bg en vez de a la ventana.
   ============================================================ */
(function () {
  const container = document.getElementById('globe-bg');
  if (!container || typeof THREE === 'undefined') return;

  /* ---------- CONFIG (paleta QNetSys) ---------- */
  const cfg = {
    arcColor: '#22d3ee',      // cyan-400, igual que .legal-modal-content a
    dotColor: '#475569',      // slate-600, sutil para no tapar el texto
    showAtmosphere: true,
    rotationSpeed: 0.40,      // más lento: es un fondo, no el protagonista
    cameraAltitude: 5.0,
    pointSize: 0.22,
    atmosphereAltitude: 0.15,
    globeOpacity: 1.0,
    arcCount: 10,
    arcInterval: 4000,
    arcAnimDuration: 2200,
    initialRotationY: 250,   // grados: qué longitud mira de frente a la cámara al cargar (0-360)
    initialTiltX: 8.6,       // grados: inclinación arriba/abajo del globo al cargar
  };

  /* ---------- SCENE SETUP ---------- */
  const R = 200;
  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(45, 1, 0.1, 4000);
  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  container.appendChild(renderer.domElement);

  const globeGroup = new THREE.Group();
  scene.add(globeGroup);
  globeGroup.rotation.x = cfg.initialTiltX * Math.PI / 180;

  function sizeToContainer() {
    const w = container.clientWidth || 1;
    const h = container.clientHeight || 1;
    camera.aspect = w / h;
    camera.position.set(0, 0, R * cfg.cameraAltitude);
    camera.lookAt(0, 0, 0);
    camera.updateProjectionMatrix();
    renderer.setSize(w, h);
  }

  /* ---------- LAND MASK ----------
     Real coastlines, baked offline from Natural Earth 1:110m data
     (world-atlas "land-110m.json" + d3-geo point-in-polygon test),
     packed as a 720x360 (0.5deg) bitmap so no runtime network fetch is needed. */
  const LAND_GRID = { cols: 720, rows: 360, step: 0.5,
    b64: ""
  };

  function decodeLandGrid(grid){
    const raw = atob(grid.b64);
    const bytes = new Uint8Array(raw.length);
    for (let i=0;i<raw.length;i++) bytes[i] = raw.charCodeAt(i);
    return bytes;
  }
  const landBytes = decodeLandGrid(LAND_GRID);
  function bitAt(bytes, index){
    return (bytes[index >> 3] >> (7 - (index % 8))) & 1;
  }
  function landMask(lat, lon){
    const { cols, rows, step } = LAND_GRID;
    let row = Math.floor((90 - lat) / step);
    let col = Math.floor((lon + 180) / step);
    row = Math.max(0, Math.min(rows-1, row));
    col = ((col % cols) + cols) % cols;
    const idx = row*cols + col;
    if (!bitAt(landBytes, idx)) return false;
    const s = Math.sin(lat*12.9898 + lon*78.233) * 43758.5453;
    const n = s - Math.floor(s);
    return n > 0.1;
  }

  /* ---------- FIBONACCI SPHERE SAMPLING FOR DOTS ---------- */
  const CANDIDATES = 75000;
  const landPoints = [];
  (function buildLand(){
    const golden = Math.PI * (3 - Math.sqrt(5));
    for (let i=0;i<CANDIDATES;i++){
      const y = 1 - (i/(CANDIDATES-1))*2;
      const radiusAtY = Math.sqrt(1-y*y);
      const theta = golden * i;
      const x = Math.cos(theta)*radiusAtY;
      const z = Math.sin(theta)*radiusAtY;
      const lat = Math.asin(y) * 180/Math.PI;
      const lon = Math.atan2(-z, x) * 180/Math.PI;
      if (landMask(lat, lon)){
        landPoints.push({ pos: new THREE.Vector3(x,y,z), lat, lon });
      }
    }
  })();

  /* ---------- DOTS ---------- */
  const dotGeo = new THREE.BufferGeometry();
  const dotPositions = new Float32Array(landPoints.length*3);
  landPoints.forEach((p,i)=>{
    dotPositions[i*3]   = p.pos.x*R;
    dotPositions[i*3+1] = p.pos.y*R;
    dotPositions[i*3+2] = p.pos.z*R;
  });
  dotGeo.setAttribute('position', new THREE.BufferAttribute(dotPositions,3));
  const dotMat = new THREE.PointsMaterial({ color: cfg.dotColor, size: cfg.pointSize*6, sizeAttenuation:true, transparent:true, opacity:0.9 });
  const dots = new THREE.Points(dotGeo, dotMat);
  globeGroup.add(dots);

  /* ---------- CORE GLOBE ---------- */
  const coreGeo = new THREE.SphereGeometry(R*0.995, 48, 48);
  const coreMat = new THREE.MeshBasicMaterial({ color:0x000000, transparent:true, opacity:cfg.globeOpacity*0.55 });
  const core = new THREE.Mesh(coreGeo, coreMat);
  globeGroup.add(core);

  /* ---------- ATMOSPHERE (rim glow, siempre acotado 0..1) ---------- */
  const atmoVert = `
    varying vec3 vNormal;
    void main(){
      vNormal = normalize(normalMatrix * normal);
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0);
    }`;
  const atmoFrag = `
    varying vec3 vNormal;
    uniform vec3 glowColor;
    void main(){
      float rim = 1.0 - abs(dot(vNormal, vec3(0.0, 0.0, 1.0)));
      float intensity = pow(clamp(rim, 0.0, 1.0), 2.5);
      gl_FragColor = vec4(glowColor, 1.0) * intensity;
    }`;
  let atmosphere = null;
  function buildAtmosphere(){
    if (atmosphere){ scene.remove(atmosphere); }
    const geo = new THREE.SphereGeometry(R*(1+cfg.atmosphereAltitude), 48, 48);
    const mat = new THREE.ShaderMaterial({
      vertexShader: atmoVert, fragmentShader: atmoFrag,
      uniforms: { glowColor: { value: new THREE.Color(cfg.dotColor) } },
      blending: THREE.AdditiveBlending, side: THREE.BackSide, transparent: true,
      depthWrite: false,
    });
    atmosphere = new THREE.Mesh(geo, mat);
    atmosphere.visible = cfg.showAtmosphere;
    scene.add(atmosphere);
  }
  buildAtmosphere();

  /* ---------- ARCS ---------- */
  const activeArcs = [];
  function randomLandPoint(){ return landPoints[Math.floor(Math.random()*landPoints.length)]; }
  function makeArc(){
    const a = randomLandPoint().pos.clone();
    const b = randomLandPoint().pos.clone();
    if (a.distanceTo(b) < 0.3) return null;
    const angle = a.angleTo(b);
    const height = 1 + Math.min(angle*0.6, 0.9);
    const mid = a.clone().add(b).multiplyScalar(0.5).normalize().multiplyScalar(height);
    const curve = new THREE.QuadraticBezierCurve3(a.clone().multiplyScalar(R), mid.clone().multiplyScalar(R), b.clone().multiplyScalar(R));
    const SEGMENTS = 64;
    const fullPoints = curve.getPoints(SEGMENTS);
    const geo = new THREE.BufferGeometry().setFromPoints(fullPoints);
    geo.setDrawRange(0, 2);
    const mat = new THREE.LineBasicMaterial({ color: cfg.arcColor, transparent:true, opacity:0.9 });
    const line = new THREE.Line(geo, mat);
    globeGroup.add(line);
    return { line, geo, mat, points: fullPoints, born: performance.now(), state:'drawing' };
  }
  let lastSpawn = 0;
  function updateArcs(now){
    const avgArcLifetime = cfg.arcAnimDuration * 2.1;
    const neededGap = cfg.arcCount > 0 ? avgArcLifetime / cfg.arcCount : cfg.arcInterval;
    const spawnGap = Math.min(cfg.arcInterval, neededGap);
    if (now - lastSpawn > spawnGap && activeArcs.length < cfg.arcCount){
      const arc = makeArc();
      if (arc) activeArcs.push(arc);
      lastSpawn = now;
    }
    for (let i=activeArcs.length-1; i>=0; i--){
      const arc = activeArcs[i];
      const t = (now - arc.born) / cfg.arcAnimDuration;
      if (arc.state==='drawing'){
        const count = Math.max(2, Math.floor(Math.min(t,1) * arc.points.length));
        arc.geo.setDrawRange(0, count);
        if (t >= 1){ arc.state='holding'; arc.holdStart = now; }
      } else if (arc.state==='holding'){
        if (now - arc.holdStart > cfg.arcAnimDuration*0.6){ arc.state='fading'; arc.fadeStart = now; }
      } else if (arc.state==='fading'){
        const ft = (now - arc.fadeStart) / (cfg.arcAnimDuration*0.5);
        arc.mat.opacity = Math.max(0, 0.9*(1-ft));
        if (ft >= 1){
          globeGroup.remove(arc.line);
          arc.geo.dispose(); arc.mat.dispose();
          activeArcs.splice(i,1);
        }
      }
    }
  }

  /* ---------- ANIMATION LOOP (solo autorotación, sin drag) ---------- */
  let autoRot = cfg.initialRotationY * Math.PI / 180;
  let running = true;
  function animate(now){
    if (!running) return;
    requestAnimationFrame(animate);
    autoRot += 0.0016 * cfg.rotationSpeed;
    globeGroup.rotation.y = autoRot;
    updateArcs(now);
    renderer.render(scene, camera);
  }

  /* ---------- Pausar cuando la sección no está en pantalla (perf) ---------- */
  sizeToContainer();
  requestAnimationFrame(animate);

  if ('ResizeObserver' in window){
    new ResizeObserver(sizeToContainer).observe(container);
  } else {
    window.addEventListener('resize', sizeToContainer);
  }

  if ('IntersectionObserver' in window){
    new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        running = entry.isIntersecting;
        if (running) requestAnimationFrame(animate);
      });
    }, { threshold: 0.05 }).observe(container);
  }
})();
